"""Catalog additions needed by the CMU Recipe Archive import.

Each entry becomes an IngredientDef in src/data/ingredients.ts plus a USDA mapping and GRAMS in
src/data/nutrition/usdaMap.ts. Allergen tags follow the catalog rule: CONSERVATIVE — tag it if a
typical store product may contain the allergen.

Fields: id, name, aisle, tags, unit (canonical recipe unit; family is derived from it), fdc
(SR Legacy fdc_id), basis, grams (per unit, for nutrition + conversion), names (normalized
archive names), and optional: staple, plural, note, can_cups (cups in one can), each_g (grams per
item when the archive counts something measured by volume/weight).
"""

A = {"P": "Produce", "M": "Meat & Seafood", "D": "Dairy & Eggs", "B": "Bakery & Bread", "G": "Pasta, Rice & Grains",
     "C": "Canned & Jarred", "O": "Oils & Condiments", "S": "Spices & Baking", "N": "Snacks & Nuts", "F": "Frozen",
     "V": "Beverages"}


def ing(id, name, aisle, tags, unit, fdc, grams, names, basis="usda", **kw):
    return {"id": id, "name": name, "aisle": A[aisle], "tags": tags, "unit": unit, "fdc": fdc, "basis": basis,
            "grams": grams, "names": names, **kw}


